int send_diseqc_message(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int result;

	if (d->msg[0] > DVB_DISEQC_MAX_MSG_LEN)
		return -EINVAL;

	if (dvb_debug >= 2)
		dvb_frontend_debug_dump(fe, "DiSEqC TX", d->msg, d->msg[0]);

	d->msg[0] |= 0x30;

	if (d->msg[1] == 0x10 || d->msg[1] == 0x11)
		d->msg[0] |= 0x40;

	if (fe->ops.set_toneburst)
		fe->ops.set_toneburst(fe, 1);

	msleep(10);

	if (fe->ops.send_diseqc_master_cmd)
		result = fe->ops.send_diseqc_master_cmd(fe, d);
	else
		result = -ENOSYS;

	msleep(10);

	if (fe->ops.set_toneburst)
		fe->ops.set_toneburst(fe, 0);

	return result;
}

int dvb_frontend_send_diseqc_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int ret;

	if (d->msg[0] > 6) {
		/* Invalid DiSEqC message length */
		return -EINVAL;
	}

	if (dvb_debug) {
		int i;
		dvb_dbg("DiSEqC message: ");
		for (i = 0; i < d->msg[0] + 1; i++)
			dvb_dbg_cont("%02x ", d->msg[i] & 0xff);
		dvb_dbg_cont("\n");
	}

	ret = dvb_frontend_prepare_tone(fe, d->msg[0] == 5 ? DVBFE_TONE_ON : DVBFE_TONE_OFF);
	if (ret < 0)
		return ret;

	ret = dvb_frontend_send_tone(fe, d->msg[0] == 5 ? DVBFE_TONE_ON : DVBFE_TONE_OFF);
	if (ret < 0)
		return ret;

	msleep(150); /* Wait for voltage to stabilize */

	ret = dvb_frontend_send_diseqc(fe, d);
	if (ret < 0)
		return ret;

	msleep(150); /* Wait for command to complete */

	return 0;
}

int dvb_diseqc_send_master_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int i, rc;
	struct dvb_diseqc_slave_reply *r = &fe->diseqc_slave_reply;
	unsigned long flags;

	if (d->msg[0] > 6)
		return -EINVAL;

	if (dvb_frontend_debug)
		dvb_diseqc_dump(0, "send", d->msg, d->msg[0] + 1);

	mutex_lock(&fe->diseqc_mutex);

	if (fe->ops.send_diseqc_master_cmd == NULL) {
		mutex_unlock(&fe->diseqc_mutex);
		return -EOPNOTSUPP;
	}

	memcpy(fe->diseqc_msg, d->msg, d->msg[0] + 1);
	fe->diseqc_msg_len = d->msg[0] + 1;

	if ((fe->diseqc_msg[0] & 0x0f) == 0x0f) {
		mutex_unlock(&fe->diseqc_mutex);
		return -EINVAL;
	}

	if ((fe->diseqc_msg[0] & 0x10) == 0x10)
		fe->ops.send_toneburst(fe, 1);
	else
		fe->ops.send_toneburst(fe, 0);

	/* wait for LNB to be ready */
	msleep(100);

	/* voltage stabilization delay */
	msleep(20);

	rc = fe->ops.send_diseqc_master_cmd(fe, fe->diseqc_msg, fe->diseqc_msg_len);

	/* wait for LNB to finish */
	msleep(100);

	mutex_unlock(&fe->diseqc_mutex);

	if (rc < 0)
		return rc;

	if (dvb_frontend_debug)
		printk(KERN_DEBUG "dvb-frontend: DiSEqC command sent successfully\n");

	return 0;
}

int dvb_frontend_send_diseqc_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int i, ret = 0;

	/* Validate DiSEqC message length */
	if (d->msg[0] != 0x10 && d->msg[0] != 0x18) {
		dvb_frontend_log(fe, FE_ERROR, "Invalid DiSEqC message type 0x%x", d->msg[0]);
		return -EINVAL;
	}

	/* Log message if debugging is enabled */
	if (dvb_frontend_debug(fe)) {
		dvb_frontend_log(fe, FE_DEBUG, "Sending DiSEqC message:");
		for (i = 0; i < d->msg_len; i++)
			dvb_frontend_log(fe, FE_DEBUG, "0x%x ", d->msg[i]);
		dvb_frontend_log(fe, FE_DEBUG, "\n");
	}

	/* Prepare message for transmission (e.g., handle toneburst) */
	if (d->msg[0] == 0x18) {
		if (fe->ops.set_voltage)
			fe->ops.set_voltage(fe, SEC_VOLTAGE_18);
	} else {
		if (fe->ops.set_voltage)
			fe->ops.set_voltage(fe, SEC_VOLTAGE_13);
	}

	/* Wait for LNB to be ready */
	msleep(150);

	/* Send the message */
	if (fe->ops.send_diseqc_master_cmd) {
		ret = fe->ops.send_diseqc_master_cmd(fe, d);
		if (ret < 0)
			return ret;
	}

	/* Wait for transmission to complete */
	msleep(150);

	return ret;
}

int send_diseqc_message(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
    if (d->msg[0] > 6) {
        return -EINVAL;
    }

    dvb_frontend_log(fe, "sending DiSEqC message");

    if (d->msg[0] >= 2) {
        if (d->msg[1] & 0x10)
            fe->ops.set_voltage(fe, SEC_VOLTAGE_18);
        else
            fe->ops.set_voltage(fe, SEC_VOLTAGE_13);
    }

    if (d->msg[0] == 4)
        fe->ops.set_tone(fe, SEC_TONE_ON);

    msleep(10);

    int ret = fe->ops.send_diseqc_cmd(fe, d);

    msleep(10);

    fe->ops.set_tone(fe, SEC_TONE_OFF);

    return ret;
}
